const crypto = require('crypto');

const REPLAY_WINDOW_SEC = 300;
const MAX_AGE_MS = 24 * 60 * 60 * 1000;
const E164 = /^\+[1-9]\d{6,14}$/;
const OPAQUE_ID = /^\S{1,128}$/;
const DEDUP_BLOCKING_STATES = ['sending', 'submitted', 'uncertain'];

// ---------- signature ----------
function parseSignatureHeader(header, nowMs) {
	if (typeof header !== 'string' || header.trim() === '') return { ok: false, reason: 'missing_signature' };
	const seen = {};
	for (const part of header.trim().split(',')) {
		const i = part.indexOf('=');
		if (i < 1) return { ok: false, reason: 'malformed_signature' };
		const k = part.slice(0, i).trim();
		const v = part.slice(i + 1).trim();
		if ((k !== 't' && k !== 's') || k in seen) return { ok: false, reason: 'malformed_signature' };
		seen[k] = v;
	}
	if (!('t' in seen) || !('s' in seen)) return { ok: false, reason: 'malformed_signature' };
	if (!/^\d{1,12}$/.test(seen.t)) return { ok: false, reason: 'malformed_signature' };
	if (!/^[0-9a-fA-F]{64}$/.test(seen.s)) return { ok: false, reason: 'malformed_signature' };
	if (Math.abs(Math.floor(nowMs / 1000) - Number(seen.t)) > REPLAY_WINDOW_SEC) {
		return { ok: false, reason: 'timestamp_out_of_range' };
	}
	return { ok: true, timestamp: seen.t, signatureHex: seen.s.toLowerCase() };
}

function signedPayload(timestamp, rawBody) {
	return Buffer.concat([Buffer.from(timestamp + '.'), rawBody]);
}

function signaturesMatch(computedHex, givenHex) {
	if (typeof computedHex !== 'string' || typeof givenHex !== 'string') return false;
	if (!/^[0-9a-fA-F]{64}$/.test(computedHex) || !/^[0-9a-fA-F]{64}$/.test(givenHex)) return false;
	const a = Buffer.from(computedHex, 'hex');
	const b = Buffer.from(givenHex, 'hex');
	if (a.length !== 32 || b.length !== 32) return false;
	return crypto.timingSafeEqual(a, b);
}

function parseJsonBody(buf) {
	try {
		const v = JSON.parse(buf.toString('utf8'));
		if (v === null || typeof v !== 'object' || Array.isArray(v)) return { ok: false, reason: 'malformed_json' };
		return { ok: true, value: v };
	} catch (e) {
		return { ok: false, reason: 'malformed_json' };
	}
}

function statusForReject(reason) {
	return reason === 'malformed_json' ? 400 : 401;
}

// ---------- classification ----------
const nonEmptyString = (v) => typeof v === 'string' && v.trim() !== '';
const digits = (phone) => String(phone).replace(/^\+/, '');

function classifyEvent(event, nowMs, cfg) {
	const ignore = (reason) => ({ action: 'ignore', reason });
	if (!event || typeof event !== 'object') return ignore('not_inbound_message');
	if (event.type !== 'whatsapp.inbound_message.received') return ignore('not_inbound_message');
	const m = event.whatsappInboundMessage;
	if (!m || typeof m !== 'object') return ignore('missing_message');
	if (m.to !== cfg.businessNumber) return ignore('other_phone');
	if (m.from === cfg.businessNumber) return ignore('echo');
	if (m.type !== 'text') return ignore('non_text');
	if (!m.text || typeof m.text.body !== 'string' || m.text.body.trim() === '') return ignore('empty_text');
	const phone = typeof m.from === 'string' && E164.test(m.from) ? m.from : null;
	const bsuid = typeof m.fromUserId === 'string' && OPAQUE_ID.test(m.fromUserId) ? m.fromUserId : null;
	if (!phone && !bsuid) return ignore('invalid_identity');
	if (!nonEmptyString(m.wabaId)) return ignore('missing_waba_id');
	const wamid = nonEmptyString(m.wamid) ? m.wamid : null;
	const inboundId = nonEmptyString(m.id) ? m.id : null;
	if (!wamid && !inboundId) return ignore('missing_message_id');
	const sent = typeof m.sendTime === 'string' ? Date.parse(m.sendTime) : NaN;
	if (Number.isNaN(sent) || sent > nowMs + REPLAY_WINDOW_SEC * 1000) return ignore('invalid_send_time');
	if (nowMs - sent > MAX_AGE_MS) return ignore('stale_message');
	return {
		action: 'process',
		accepted: {
			eventId: nonEmptyString(event.id) ? event.id : '',
			wabaId: m.wabaId,
			wamid,
			inboundId,
			businessNumber: cfg.businessNumber,
			from: phone,
			fromUserId: bsuid,
			fromParentUserId: nonEmptyString(m.fromParentUserId) ? m.fromParentUserId : null,
			customerProfile: m.customerProfile && typeof m.customerProfile === 'object' ? m.customerProfile : null,
			sendTime: m.sendTime,
			text: m.text.body,
			messageKey: m.wabaId + '|' + cfg.businessNumber + '|' + (wamid || inboundId),
		},
	};
}

function normalizeEvent(acc, cfg) {
	if (!acc || (!acc.from && !acc.fromUserId)) throw new Error('Missing customer identity');
	const contact = { profile: acc.customerProfile || {} };
	if (acc.fromUserId) contact.user_id = acc.fromUserId;
	if (acc.from) contact.wa_id = digits(acc.from);
	const message = {
		id: acc.wamid || acc.inboundId,
		timestamp: String(Math.floor(Date.parse(acc.sendTime) / 1000)),
		type: 'text',
		text: { body: acc.text },
	};
	if (acc.from) message.from = digits(acc.from);
	if (acc.fromUserId) message.from_user_id = acc.fromUserId;
	return {
		contacts: [contact],
		messages: [message],
		metadata: { display_phone_number: digits(cfg.businessNumber) },
		memory_key: 'twodazzle:prod:ycloud:' + digits(cfg.businessNumber) + ':' + (acc.fromUserId || digits(acc.from)),
		ycloud: acc,
	};
}

// ---------- outbound ----------
function cleanAnswer(text) {
	let t = String(text == null ? '' : text);
	t = t.replace(/\*+/g, '').replace(/~~/g, '');
	t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1 $2');
	t = t.replace(/\n{3,}/g, '\n\n').trim();
	t = t.replace(/^.*?based on the document you provided[,:]?\s*/i, '');
	return t;
}

function buildSendRequest(acc, answer, cfg) {
	if (typeof answer !== 'string' || answer.trim() === '') throw new Error('Empty or invalid answer');
	const phone = acc && typeof acc.from === 'string' && E164.test(acc.from) ? acc.from : null;
	const bsuid = acc && typeof acc.fromUserId === 'string' && OPAQUE_ID.test(acc.fromUserId) ? acc.fromUserId : null;
	if (!phone && !bsuid) throw new Error('No valid destination');
	const externalId = 'tdz-' + crypto.createHash('sha256').update(String(acc.messageKey)).digest('hex').slice(0, 32);
	const body = { from: cfg.businessNumber, type: 'text' };
	if (phone) body.to = phone;
	else body.recipient = bsuid;
	body.text = { body: answer.trim() };
	body.externalId = externalId;
	return { body };
}

function classifySendOutcome(res) {
	if (!res || typeof res !== 'object') return { state: 'uncertain', providerId: '', error: 'no_response' };
	const status = Number(res.statusCode);
	if (!Number.isFinite(status) || status === 0) {
		const e = res.error;
		const msg = e && (e.message || e.code) ? String(e.message || e.code) : 'transport_error';
		return { state: 'uncertain', providerId: '', error: 'transport: ' + msg };
	}
	if (status >= 200 && status < 300) {
		const id = res.body && typeof res.body === 'object' ? res.body.id : undefined;
		if (typeof id === 'string' && id.trim() !== '') return { state: 'submitted', providerId: id, error: '' };
		return { state: 'uncertain', providerId: '', error: 'http_' + status + '_without_provider_id' };
	}
	if (status === 408 || status >= 500) return { state: 'uncertain', providerId: '', error: 'http_' + status + '_ambiguous' };
	const detail = res.body && res.body.error && res.body.error.message ? ': ' + String(res.body.error.message).slice(0, 300) : '';
	return { state: 'failed', providerId: '', error: 'http_' + status + '_rejected' + detail };
}

// ---------- lock / ledger protocol ----------
function isLockOwned(row, execId) {
	return !!row && row.state === 'busy' && typeof row.owner === 'string' && row.owner !== '' && row.owner === String(execId);
}

async function tryClaimLock(store, lockId, execId) {
	if (execId === undefined || execId === null || String(execId) === '') throw new Error('Missing execution id');
	await store.casUpdate(lockId, { state: 'idle' }, { state: 'busy', owner: String(execId) });
	const fresh = await store.getRow(lockId); // never trust the update result: re-read and verify ownership
	return isLockOwned(fresh, execId);
}

async function releaseLock(store, lockId, execId) {
	return store.casUpdate(lockId, { state: 'busy', owner: String(execId) }, { state: 'idle', owner: '' });
}

function decideDedup(rows, ownRowId) {
	const hit = (rows || []).find((r) => r && r.id !== ownRowId && DEDUP_BLOCKING_STATES.includes(r.state));
	return { duplicate: !!hit, matchId: hit ? hit.id : null };
}

async function processEvent(deps, ctx) {
	const { store, lockRowId } = deps;
	const { execId, inboxRowId, accepted, normalized } = ctx;
	let claimed = false;
	for (let attempt = 1; attempt <= deps.maxAttempts; attempt++) {
		if (await tryClaimLock(store, lockRowId, execId)) { claimed = true; break; }
		if (attempt < deps.maxAttempts) await deps.wait(attempt);
	}
	if (!claimed) {
		await store.updateRow(inboxRowId, { error: 'lock_wait_exhausted after ' + deps.maxAttempts + ' attempts; row left pending for manual recovery' });
		return { result: 'lock_timeout' };
	}
	try {
		const rows = await store.queryByKey(accepted.messageKey);
		if (decideDedup(rows, inboxRowId).duplicate) {
			await store.updateRow(inboxRowId, { state: 'suppressed_duplicate' });
			return { result: 'suppressed_duplicate' };
		}
		let request;
		try {
			const raw = await deps.llm(normalized);
			request = buildSendRequest(accepted, cleanAnswer(raw), { businessNumber: deps.businessNumber });
		} catch (e) {
			await store.updateRow(inboxRowId, { state: 'failed', error: 'before_send: ' + String(e && e.message ? e.message : e).slice(0, 500) });
			return { result: 'failed_before_send' };
		}
		await store.updateRow(inboxRowId, { state: 'sending', owner: String(execId) });
		let res;
		try {
			res = await deps.http(request.body);
		} catch (e) {
			res = { error: { message: e && e.message, code: e && e.code } };
		}
		const o = classifySendOutcome(res);
		await store.updateRow(inboxRowId, { state: o.state, provider_id: o.providerId, error: o.error });
		return { result: o.state };
	} finally {
		await releaseLock(store, lockRowId, execId);
	}
}

