// ---------- lock / ledger protocol ----------
function isLockOwned(row, execId) {
	return !!row && row.state === 'busy' && typeof row.owner === 'string' && row.owner !== '' && row.owner === String(execId);
}

async function tryClaimLock(store, lockId, execId) {
	if (execId === undefined || execId === null || String(execId) === '') throw new Error('Missing execution id');
	await store.casUpdate(lockId, { state: 'idle' }, { state: 'busy', owner: String(execId) });
	const fresh = await store.getRow(lockId); // never trust the update result: re-read and verify ownership
	return isLockOwned(fresh, execId);
}

async function releaseLock(store, lockId, execId) {
	return store.casUpdate(lockId, { state: 'busy', owner: String(execId) }, { state: 'idle', owner: '' });
}

function decideDedup(rows, ownRowId) {
	const hit = (rows || []).find((r) => r && r.id !== ownRowId && DEDUP_BLOCKING_STATES.includes(r.state));
	return { duplicate: !!hit, matchId: hit ? hit.id : null };
}

async function processEvent(deps, ctx) {
	const { store, lockRowId } = deps;
	const { execId, inboxRowId, accepted, normalized } = ctx;
	let claimed = false;
	for (let attempt = 1; attempt <= deps.maxAttempts; attempt++) {
		if (await tryClaimLock(store, lockRowId, execId)) { claimed = true; break; }
		if (attempt < deps.maxAttempts) await deps.wait(attempt);
	}
	if (!claimed) {
		await store.updateRow(inboxRowId, { error: 'lock_wait_exhausted after ' + deps.maxAttempts + ' attempts; row left pending for manual recovery' });
		return { result: 'lock_timeout' };
	}
	try {
		const rows = await store.queryByKey(accepted.messageKey);
		if (decideDedup(rows, inboxRowId).duplicate) {
			await store.updateRow(inboxRowId, { state: 'suppressed_duplicate' });
			return { result: 'suppressed_duplicate' };
		}
		let request;
		try {
			const raw = await deps.llm(normalized);
			request = buildSendRequest(accepted, cleanAnswer(raw), { businessNumber: deps.businessNumber });
		} catch (e) {
			await store.updateRow(inboxRowId, { state: 'failed', error: 'before_send: ' + String(e && e.message ? e.message : e).slice(0, 500) });
			return { result: 'failed_before_send' };
		}
		await store.updateRow(inboxRowId, { state: 'sending', owner: String(execId) });
		let res;
		try {
			res = await deps.http(request.body);
		} catch (e) {
			res = { error: { message: e && e.message, code: e && e.code } };
		}
		const o = classifySendOutcome(res);
		await store.updateRow(inboxRowId, { state: o.state, provider_id: o.providerId, error: o.error });
		return { result: o.state };
	} finally {
		await releaseLock(store, lockRowId, execId);
	}
}

