const crypto = require('crypto');

const REPLAY_WINDOW_SEC = 300;
const MAX_AGE_MS = 24 * 60 * 60 * 1000;
const E164 = /^\+[1-9]\d{6,14}$/;
const OPAQUE_ID = /^\S{1,128}$/;
const DEDUP_BLOCKING_STATES = ['sending', 'submitted', 'uncertain'];

// ---------- signature ----------
function parseSignatureHeader(header, nowMs) {
	if (typeof header !== 'string' || header.trim() === '') return { ok: false, reason: 'missing_signature' };
	const seen = {};
	for (const part of header.trim().split(',')) {
		const i = part.indexOf('=');
		if (i < 1) return { ok: false, reason: 'malformed_signature' };
		const k = part.slice(0, i).trim();
		const v = part.slice(i + 1).trim();
		if ((k !== 't' && k !== 's') || k in seen) return { ok: false, reason: 'malformed_signature' };
		seen[k] = v;
	}
	if (!('t' in seen) || !('s' in seen)) return { ok: false, reason: 'malformed_signature' };
	if (!/^\d{1,12}$/.test(seen.t)) return { ok: false, reason: 'malformed_signature' };
	if (!/^[0-9a-fA-F]{64}$/.test(seen.s)) return { ok: false, reason: 'malformed_signature' };
	if (Math.abs(Math.floor(nowMs / 1000) - Number(seen.t)) > REPLAY_WINDOW_SEC) {
		return { ok: false, reason: 'timestamp_out_of_range' };
	}
	return { ok: true, timestamp: seen.t, signatureHex: seen.s.toLowerCase() };
}

function signedPayload(timestamp, rawBody) {
	return Buffer.concat([Buffer.from(timestamp + '.'), rawBody]);
}

function signaturesMatch(computedHex, givenHex) {
	if (typeof computedHex !== 'string' || typeof givenHex !== 'string') return false;
	if (!/^[0-9a-fA-F]{64}$/.test(computedHex) || !/^[0-9a-fA-F]{64}$/.test(givenHex)) return false;
	const a = Buffer.from(computedHex, 'hex');
	const b = Buffer.from(givenHex, 'hex');
	if (a.length !== 32 || b.length !== 32) return false;
	return crypto.timingSafeEqual(a, b);
}

function parseJsonBody(buf) {
	try {
		const v = JSON.parse(buf.toString('utf8'));
		if (v === null || typeof v !== 'object' || Array.isArray(v)) return { ok: false, reason: 'malformed_json' };
		return { ok: true, value: v };
	} catch (e) {
		return { ok: false, reason: 'malformed_json' };
	}
}

